import{_ as i,o as e,c as n,ai as a}from"./chunks/framework.ETupdKIa.js";const D=JSON.parse('{"title":"Dependency Injection","description":"","frontmatter":{},"headers":[],"relativePath":"til/Spring/20240508_DI.md","filePath":"til/Spring/20240508_DI.md"}'),t={name:"til/Spring/20240508_DI.md"};function u(o,l,r,c,d,p){return e(),n("div",null,[...l[0]||(l[0]=[a('<h1 id="dependency-injection" tabindex="-1">Dependency Injection <a class="header-anchor" href="#dependency-injection" aria-label="Permalink to “Dependency Injection”">​</a></h1><h2 id="汚いメモ" tabindex="-1">汚いメモ <a class="header-anchor" href="#汚いメモ" aria-label="Permalink to “汚いメモ”">​</a></h2><ul><li>DIに関する基本的な用語 <ul><li>DIコンテナ(Application Context)</li><li>コンフィギュレーション</li><li>Bean定義</li><li>Bean</li></ul></li><li>Beanとは <ul><li>DIコンテナで管理されるオブジェクトのこと。</li></ul></li><li>Bean定義とは <ul><li>Beanとして管理したい具象クラスを指定すること(←少し説明がおかしい)</li><li>Bean定義の方法は次の3つ。 <ul><li>ステレオタイプアノテーション <ul><li>Bean管理したい具象クラスに以下のいずれかのアノテーションをつける。 <ul><li>@Searvice, @Controller, @Component, @Repository</li></ul></li></ul></li><li>Beanメソッド <ul><li>@Beanを付与したメソッドのこと。</li><li>Bean管理したい具象クラスのオブジェクトを戻り値とする。</li><li>@Configurationを付与したクラス内(JavaConfig)内で定義されるメソッド。</li></ul></li><li>beanタグ？ <ul><li>xml?でBean定義する方法。よくわからん。</li></ul></li></ul></li></ul></li><li>コンフィギュレーションとは <ul><li>DIコンテナに読み込ませる情報を記載したクラス。通称JavaConfig。</li><li>@Configurationを付与する。</li><li>@ComponentScanを付与することで、JavaConfigを基点とするパッケージとその子パッケージを範囲としてコンポーネントスキャンが行われる。 <ul><li>コンポーネントスキャンが行われると、対象範囲にあるステレオタイプアノテーションがついた具象クラスのオブジェクトがDIコンテナに登録される。</li></ul></li></ul></li><li>DIコンテナとは <ul><li>Beanを登録・管理するオブジェクト。</li><li>ApplicationContextの具象クラスがDIコンテナと呼ばれる。</li><li>DIコンテナのオブジェクトがコンストラクタで作られる場合は、コンストラクタの引数にコンフィグレーションが渡される。個数はわすれた。</li><li>引数に渡したコンフィギュレーションに@ComponentScanが付与されている場合はコンポーネントスキャンが行われ、ステレオタイプアノテーションがついた具象クラスがDIコンテナに登録される。</li></ul></li><li>Dependency Injection(依存性注入)とは <ul><li>依存する側のオブジェクトのフィールドに依存される側のオブジェクトをセットすること。</li><li>インジェクションの方法は３つ。 <ul><li>コンストラクタインジェクション <ul><li>依存する側のオブジェクトのコンストラクタに@Autowiredを付与する。</li><li>コンストラクタが一つしかない場合は@Autowiredを付与する必要なし。</li><li>コンストラクタ実行時に、引数に設定された依存オブジェクトをDIコンテナから探し、引数に渡して、フィールドにセットされる。</li></ul></li><li>Setterインジェクション <ul><li>依存する側のオブジェクトのSetterに@Autowiredを付与する。</li></ul></li><li>フィールドインジェクション <ul><li>依存する側のオブジェクトのフィールドに@Autowiredを付与する。</li></ul></li></ul></li><li>３つの中ではコンストラクタインジェクションが最もおすすめ？ <ul><li>理由 <ul><li>依存する側のフィールドにfinal修飾子をつけた上でコンストラクタで依存性注入することで、開発者がフィールドの内容を勝手に変更できないようにできるから。</li></ul></li></ul></li></ul></li><li>Beanメソッドについて <ul><li>JavaConfigに定義することができる、@Beanを付与したメソッドのこと。</li><li>DIコンテナで管理したいオブジェクトを戻り値とするメソッド。</li><li>依存性注入したい場合はBeanメソッドの引数に依存オブジェクトのクラスを型とする引数を設定する。</li><li>SpringがDIコンテナからそのオブジェクトを探して注入してくれる。</li><li>ステレオタイプアノテーションとBeanメソッドのどちらでBean定義するか問題。 <ul><li>自作のクラス→ステレオタイプアノテーションが良い。クラス数が多くなる可能性が高いから。</li><li>ライブラリで提供されるクラス→Beanメソッドが良い（でしか無理） <ul><li>DataSourceインターフェースを実装した具象クラスなどはライブラリで提供されるが、これはBeanメソッドでBean定義する。メソッド内でDB接続先などを設定する。</li></ul></li></ul></li></ul></li></ul>',3)])])}const B=i(t,[["render",u]]);export{D as __pageData,B as default};
